uv run scripts/lookup.py R17-025 2>/dev/null >/dev/null; python3 - <<'EOF'
import json
segs={}
for line in open('corpus/segments.jsonl'):
    d=json.loads(line); segs[d['segment_id']]=d['text']
for line in open('coding/acts/R17-p1.jsonl'):
    d=json.loads(line)
    if d['segment_id'] in ('R17-025','R17-065'):
        q=d['quote']
        t=' '.join(segs[d['segment_id']].split()); q2=' '.join(q.split())
        print(d['segment_id'], q2 in t)
EOF
